import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./Register.css";

const Register = () => {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    username: "",
    email: "",
    password: "",
    confirm: "",
  });

  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const [showPass, setShowPass] = useState(false);
  const [dark, setDark] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const passwordStrength = () => {
    if (form.password.length < 4) return "Weak";
    if (form.password.length < 8) return "Medium";
    return "Strong";
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setError("");

    if (!form.username || !form.email || !form.password || !form.confirm) {
      setError("⚠️ All fields are required");
      return;
    }

    if (form.password !== form.confirm) {
      setError("❌ Passwords do not match");
      return;
    }

    setSuccess(true);

    setTimeout(() => {
      navigate("/login");
    }, 1500);
  };

  return (
    <div className={`register-container ${dark ? "dark" : ""}`}>
      <form className="register-card" onSubmit={handleSubmit}>
        <div className="top-bar">
          <h2>📝 Register</h2>
          <button
            type="button"
            className="dark-toggle"
            onClick={() => setDark(!dark)}
          >
            {dark ? "☀️" : "🌙"}
          </button>
        </div>

        <p className="tagline">Create your emergency account</p>

        {error && <div className="error-box">{error}</div>}
        {success && <div className="success-box">🎉 Registration Successful</div>}

        <input
          type="text"
          name="username"
          placeholder="Username"
          value={form.username}
          onChange={handleChange}
        />

        <input
          type="email"
          name="email"
          placeholder="Email"
          value={form.email}
          onChange={handleChange}
        />

        <div className="password-box">
          <input
            type={showPass ? "text" : "password"}
            name="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
          />
          <span onClick={() => setShowPass(!showPass)}>
            {showPass ? "🙈" : "👁️"}
          </span>
        </div>

        <div className={`strength ${passwordStrength().toLowerCase()}`}>
          Password strength: {passwordStrength()}
        </div>

        <input
          type={showPass ? "text" : "password"}
          name="confirm"
          placeholder="Confirm Password"
          value={form.confirm}
          onChange={handleChange}
        />

        <button type="submit">Create Account</button>

        <p className="login-text">
          Already registered? <Link to="/login">Login</Link>
        </p>
      </form>
    </div>
  );
};

export default Register;
